previewCss:
.darma-loader-darma-b10-sprout-grow { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #65a30d); width: var(--loader-size, 84px); height: var(--loader-size, 84px); display: grid; place-items: end center; }
.darma-loader-darma-b10-sprout-grow .darma-loader-darma-b10-sprout-grow__plant { position: relative; width: calc(var(--loader-size, 84px) * .06); height: 62%; background: linear-gradient(var(--accent-2), color-mix(in srgb, #fff 25%, var(--accent-2))); border-radius: 4px; transform-origin: 50% 100%; animation: darma-loader-darma-b10-sprout-grow-grow calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b10-sprout-grow .darma-loader-darma-b10-sprout-grow__plant span { position: absolute; width: calc(var(--loader-size, 84px) * .26); height: calc(var(--loader-size, 84px) * .16); background: var(--accent); }
.darma-loader-darma-b10-sprout-grow .darma-loader-darma-b10-sprout-grow__plant span:nth-child(1) { top: 2%; right: 60%; border-radius: 0 100% 0 100%; transform-origin: right center; transform: rotate(20deg); }
.darma-loader-darma-b10-sprout-grow .darma-loader-darma-b10-sprout-grow__plant span:nth-child(2) { top: 24%; left: 60%; border-radius: 100% 0 100% 0; transform-origin: left center; transform: rotate(-20deg); }
@keyframes darma-loader-darma-b10-sprout-grow-grow { 0% { transform: scaleY(0); } 65%, 92% { transform: scaleY(1); } 100% { transform: scaleY(1); opacity: .2; } }

